sp_widget.client_script:
api.controller = function() {

    var c = this;

    /*
     * Redirect the user to the interface
     * selected by the server.
     */

    setTimeout(function() {

        if (c.data.redirect) {

            window.location.href =
                "?id=" + encodeURIComponent(c.data.redirect);

        }

    }, 500);

};

sp_widget.css:
/* =========================================
   CFMS ROLE ROUTER
   ========================================= */

.cfms-router {
    min-height: 100vh;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #f0fbfc;

    font-family: "Segoe UI",
                 Tahoma,
                 Geneva,
                 Verdana,
                 sans-serif;

    padding: 30px;

    box-sizing: border-box;
}


/* =========================================
   ROUTER CARD
   ========================================= */

.cfms-router-card {
    width: 100%;
    max-width: 450px;

    padding: 45px 35px;

    box-sizing: border-box;

    background: white;

    border-radius: 18px;

    text-align: center;

    box-shadow:
        0 10px 35px rgba(0, 0, 0, 0.10);
}


/* =========================================
   ICON
   ========================================= */

.cfms-router-icon {
    width: 75px;
    height: 75px;

    margin: 0 auto 20px auto;

    border-radius: 50%;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #e0f7fa;

    color: #00acc1;

    font-size: 32px;
}


/* =========================================
   TITLE
   ========================================= */

.cfms-router-card h2 {
    margin: 0 0 8px 0;

    color: #00acc1;

    font-size: 30px;

    font-weight: 700;
}

.cfms-router-card h3 {
    margin: 0 0 15px 0;

    color: #263238;

    font-size: 20px;

    font-weight: 600;
}


/* =========================================
   DESCRIPTION
   ========================================= */

.cfms-router-card p {
    margin: 0;

    color: #546e7a;

    font-size: 14px;

    line-height: 1.6;
}


/* =========================================
   LOADER
   ========================================= */

.router-loader {
    margin-top: 25px;

    display: flex;

    justify-content: center;

    align-items: center;

    gap: 7px;
}

.router-loader span {
    width: 9px;
    height: 9px;

    border-radius: 50%;

    background: #00acc1;

    animation: cfmsLoader 1.2s infinite ease-in-out;
}

.router-loader span:nth-child(2) {
    animation-delay: 0.15s;
}

.router-loader span:nth-child(3) {
    animation-delay: 0.3s;
}


@keyframes cfmsLoader {

    0%,
    80%,
    100% {
        transform: scale(0.7);

        opacity: 0.5;
    }

    40% {
        transform: scale(1);

        opacity: 1;
    }

}


/* =========================================
   MOBILE
   ========================================= */

@media (max-width: 600px) {

    .cfms-router {
        padding: 20px;
    }

    .cfms-router-card {
        padding: 35px 25px;
    }

    .cfms-router-card h2 {
        font-size: 26px;
    }

    .cfms-router-card h3 {
        font-size: 18px;
    }

}

sp_widget.script:
(function() {

    data.redirect = "cfms_home";


    if (!gs.isLoggedIn()) {

        data.redirect = "cfms_login";

        return;

    }


    /*
     * Admin
     */

    if (gs.hasRole("admin")) {

        data.redirect =
            "cfms_admin";

        return;

    }


    /*
     * Manager
     */

    if (gs.hasRole("cfms_manager")) {

        data.redirect =
            "cfms_manager";

        return;

    }


    /*
     * Staff
     */

    if (gs.hasRole("cfms_staff")) {

        data.redirect =
            "cfms_staff";

        return;

    }


    /*
     * Student
     */

    if (gs.hasRole("cfms_student")) {

        data.redirect =
            "cfms_student";

        return;

    }


    /*
     * Default
     */

    data.redirect =
        "cfms_home";

})();
